import {combinations,choose,sample,randomInt,wilson,uniqueLines,targetProbability} from './engine.mjs';
self.onmessage=({data})=>{try{const {g,r,extra,trials=60000}=data,lines=uniqueLines(data.lines);if(r===g.k){const distinct=extra?lines.length:new Set(lines.map(l=>l.main.join(','))).size;const p=distinct/(Number(choose(g.n,g.k))*(extra&&g.m?Number(choose(g.m,g.j)):1));postMessage({done:true,exact:true,p,low:p,high:p,n:0});return;}const matches=(draw,e)=>{const set=new Set(draw);return lines.some(l=>l.main.reduce((s,n)=>s+set.has(n),0)>=r&&(!extra||l.extra.every(x=>e.includes(x))));};const pool=Array.from({length:g.n},(_,i)=>i+1),ep=Array.from({length:g.m},(_,i)=>i+1);const total=Number(choose(g.n,g.k))*(extra&&g.m?Number(choose(g.m,g.j)):1);const exact=total<=500000&&total*lines.length*g.k<=45000000;let hits=0,n=0;if(lines.length===1){const p=targetProbability(g,r,extra);postMessage({done:true,exact:true,p,low:p,high:p,n:0});return;}if(exact){const extras=extra&&g.m?[...combinations(ep,g.j)]:[[]];for(const main of combinations(pool,g.k)){for(const e of extras){hits+=matches(main,e)?1:0;n++;}if(n%20000===0)postMessage({progress:n/total});}}else{for(let i=0;i<trials;i++){hits+=matches(sample(pool,g.k),extra?sample(ep,g.j):[])?1:0;n++;if(n%5000===0)postMessage({progress:n/trials});}}const p=hits/n,[low,high]=exact?[p,p]:wilson(hits,n);postMessage({done:true,exact,p,low,high,n,hits});}catch(e){postMessage({error:e.message});}};
